const file = $input.first();
const triggerData = $('Google Drive - Watch Folder').first().json;

const mimeType = triggerData.mimeType || 'image/jpeg';
const fileName = triggerData.name || 'asset';
const fileId = triggerData.id;
const webViewLink = triggerData.webViewLink || '';

const isVideo = mimeType.startsWith('video/');
const isImage = mimeType.startsWith('image/');

let base64Data = '';
if (file.binary && file.binary.data) {
  base64Data = file.binary.data.data || '';
}

return [{
  json: {
    fileId,
    fileName,
    mimeType,
    isVideo,
    isImage,
    webViewLink,
    base64Data,
    assetType: isVideo ? 'video' : 'image'
  },
  binary: file.binary
}];

