const response = $input.first().json;
const rawContent = response.choices[0].message.content;

let captions;
try {
  captions = JSON.parse(rawContent);
} catch (e) {
  const cleaned = rawContent.replace(/```json/g, '').replace(/```/g, '').trim();
  captions = JSON.parse(cleaned);
}

const assetMeta = $('Extract Vision Description').first().json;

const fbCaption = captions.facebook.caption + '\n\n' + (captions.facebook.hashtags || []).join(' ');
const igCaption = captions.instagram.caption + '\n\n' + (captions.instagram.hashtags || []).join(' ');
const ttCaption = captions.tiktok.caption + '\n\n' + (captions.tiktok.hashtags || []).join(' ');

return [{
  json: {
    ...assetMeta,
    captions: {
      facebook: fbCaption,
      instagram: igCaption,
      tiktok: ttCaption
    },
    rawCaptions: captions,
    generatedAt: new Date().toISOString()
  }
}];

const containerResponse = $input.first().json;
const containerId = containerResponse.id;

return [{
  json: {
    containerId,
    caption: $('Parse & Format Captions').first().json.captions.instagram
  }
}];

