const fbResult = (() => {
  try { return $('Facebook - Upload Image Draft').first().json; } catch(e) {
    try { return $('Facebook - Upload Video Draft').first().json; } catch(e2) { return {}; }
  }
})();

const igResult = (() => {
  try { return $('Instagram - Publish Post').first().json; } catch(e) { return {}; }
})();

const ttResult = (() => {
  try { return $('TikTok - Upload Draft').first().json; } catch(e) { return {}; }
})();

const meta = $('Parse & Format Captions').first().json;

const summary = {
  workflow: 'RRE-AUTO-03 Multi-Channel Content Distributor',
  processedAt: new Date().toISOString(),
  asset: {
    name: meta.fileName,
    type: meta.assetType,
    driveId: meta.fileId
  },
  visualDescription: meta.visualDescription,
  results: {
    facebook: {
      status: fbResult.id ? 'SUCCESS' : 'CHECK_MANUALLY',
      postId: fbResult.id || null,
      caption: meta.captions.facebook
    },
    instagram: {
      status: igResult.id ? 'SUCCESS' : 'CHECK_MANUALLY',
      postId: igResult.id || null,
      caption: meta.captions.instagram
    },
    tiktok: {
      status: ttResult.publish_id ? 'DRAFT_SAVED' : 'CHECK_MANUALLY',
      publishId: ttResult.publish_id || null,
      caption: meta.captions.tiktok
    }
  }
};

return [{ json: summary }];

